def transform(name,text):
 text=text.replace('native_onpolicy_arm_collection_v42','native_onpolicy_arm_collection_v52').replace('native_onpolicy_calibration_data_v31','native_onpolicy_calibration_data_v35')
 text=text.replace('outputs/native_onpolicy_arm_collection_v52/CPU_contract_checks_v2.json','outputs/native_onpolicy_arm_collection_v52/CPU_contract_checks_v1.json').replace('outputs/native_onpolicy_arm_collection_v52/CPU_actual_host_exit_v2.json','outputs/native_onpolicy_arm_collection_v52/CPU_actual_host_exit_v1.json')
 if name=='runtime.py':
  text=text.replace('assert lanes in(4,8,9,10)','assert lanes in(4,8,9,10,12)')
  anchor='    raw=lambda:c.call(lane,observe,task)\n';assert text.count(anchor)==1;text=text.replace(anchor,RAW)
 if name=='startup.py':text=text.replace('assert lanes in(4,8,9,10)','assert lanes in(4,8,9,10,12)')
 if name=='dispatch_checks.py':text=text.replace('range(10)','range(12)').replace('done[0]<10','done[0]<12').replace('native_lanes_fixture=10','native_lanes_fixture=12')
 if name=='known_preparation.py':
  anchor=' cache={};requests={};keys={};diagnostics={};refs={};canonical=[]\n';assert text.count(anchor)==1
  text=text.replace(anchor,' from native_fixed_FIT_inputs_v4.verify import extra_roots as extra_fourteen_roots\n extra14,extra14_inputs=extra_fourteen_roots(seed_start);roots.extend(extra14);inputs.update(extra14_inputs)\n'+anchor)
 if name=='host.py':text=text.replace('from native_server_rule4_v12.admission import','from native_server_rule4_v13.admission import').replace('from native_authenticated_history_audit_v1.audit import','from native_authenticated_history_audit_v2.audit import')
 if name=='collection_plan.py':
  anchor='  from native_unread_capture_full_v1.budget import require_planned_full_batch\n';assert text.count(anchor)==1;text=text.replace(anchor,PLAN+anchor)
 return text.replace('outputs/native_onpolicy_arm_collection_v52/CPU_contract_checks_v1.json','outputs/native_onpolicy_arm_collection_v52/CPU_contract_checks_v2.json').replace('outputs/native_onpolicy_arm_collection_v52/CPU_actual_host_exit_v1.json','outputs/native_onpolicy_arm_collection_v52/CPU_actual_host_exit_v2.json')

